insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-16','grammar','A2',14,'Present Perfect: just, already, yet','Yaqinda bo''lgan ishlar','[{"h": "just: hozirgina", "p": ["just \"hozirgina, endigina\" degani. have/has bilan 3-shakl orasiga qo''yiladi."], "e": [["I have just finished my homework.", "Uy vazifamni hozirgina tugatdim."], ["She has just left.", "U endigina ketdi."]]}, {"h": "already va yet", "t": {"head": ["So''z", "Qayerda", "Misol"], "rows": [["already (allaqachon)", "tasdiq gapda, o''rtada", "I have already eaten."], ["yet (hali / allaqachonmi)", "inkor va so''roqda, oxirida", "I haven''t eaten yet. / Have you eaten yet?"]]}}, {"h": "Qisqartmalar", "p": ["I have = I''ve, she has = she''s, have not = haven''t, has not = hasn''t."], "w": "yet tasdiq gapda ishlatilmaydi: I have finished yet deyilmaydi. To''g''risi: I have already finished."}]'::jsonb,'["just: hozirgina (have + just + 3-shakl).", "already: tasdiq gapda.", "yet: inkor va so''roq gap oxirida."]'::jsonb,false,true);
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-16',0,'fill','{"q": "I have ___ finished my lunch. It was 2 minutes ago.", "opts": ["just", "yet", "ever"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "just"}'::jsonb,null from e;
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-16',1,'fill','{"q": "Have you done your homework ___?", "opts": ["yet", "already", "just"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "yet"}'::jsonb,'yet so''roq gap oxirida keladi.' from e;
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-16',2,'fill','{"q": "She has ___ seen this film. She doesn''t want to watch it again.", "opts": ["already", "yet", "never"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "already"}'::jsonb,null from e;
