insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-17','grammar','A2',15,'Present Perfect: for va since','Hozirgacha davom etayotgan holat','[{"h": "Hozirgacha davom etadi", "p": ["Ish o''tmishda boshlanib, hozir ham davom etsa Present Perfect ishlatiladi: I have lived here for five years. (Bu yerda besh yildan beri yashayman.)"]}, {"h": "for yoki since?", "t": {"head": ["So''z", "Nimani bildiradi", "Misollar"], "rows": [["for", "davomiylik (qancha vaqt)", "for two hours, for a week, for 10 years"], ["since", "boshlanish nuqtasi (qachondan)", "since Monday, since 2020, since 9 o''clock"]]}}, {"h": "How long?", "e": [["How long have you known him?", "Uni qancha vaqtdan beri taniysan?"], ["I have known him since school.", "Uni maktabdan beri taniyman."]], "w": "O''zbekchada \"beri\" deymiz, lekin inglizchada Present Simple emas: I live here since 2020 xato. To''g''risi: I have lived here since 2020."}]'::jsonb,'["Davom etayotgan holat: have/has + 3-shakl.", "for + muddat (two years).", "since + boshlanish vaqti (2020)."]'::jsonb,false,true);
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-17',0,'fill','{"q": "I have lived in Tashkent ___ 2019.", "opts": ["since", "for", "from"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "since"}'::jsonb,null from e;
