insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-18','grammar','A2',16,'Present Perfect yoki Past Simple?','Qachon qaysi biri','[{"h": "Asosiy farq", "t": {"head": ["Past Simple", "Present Perfect"], "rows": [["Vaqt aniq: yesterday, last year, in 2020, ago", "Vaqt aytilmagan yoki muhim emas"], ["I lost my keys yesterday.", "I have lost my keys. (Hozir kalitim yo''q.)"], ["When did you go?", "Have you ever been there?"]]}}, {"h": "Natija hozir muhim", "p": ["Present Perfect natija hozir ko''rinib turganda ishlatiladi: She has broken her arm. (Qo''li hozir singan.)", "Hikoya qilganda, aniq vaqt aytilganda Past Simple: She broke her arm last summer."]}, {"h": "So''roq zanjiri", "e": [["Have you ever been to Bukhara? Yes, I have.", "Hech Buxoroda bo''lganmisan? Ha."], ["When did you go there? I went there last year.", "Qachon borgansan? O''tgan yili bordim."]], "w": "When? bilan Present Perfect ishlatilmaydi: When have you gone? xato. To''g''risi: When did you go?"}]'::jsonb,'["Aniq vaqt (yesterday, ago, in 2020): Past Simple.", "Vaqt aytilmasa yoki natija hozir muhim: Present Perfect.", "When? so''rog''i doim Past Simple."]'::jsonb,false,true);
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-18',0,'fill','{"q": "I ___ him yesterday.", "opts": ["saw", "have seen", "see"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "saw"}'::jsonb,'yesterday aniq vaqt: Past Simple.' from e;
