insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-19','grammar','A2',17,'used to','O''tmishdagi odatlar','[{"h": "Ilgari shunday edi", "p": ["used to + fe''l o''tmishda bo''lgan, hozir esa yo''q odat yoki holatni bildiradi."], "e": [["I used to play football every day.", "Ilgari har kuni futbol o''ynardim."], ["There used to be a cinema here.", "Bu yerda ilgari kinoteatr bor edi."]]}, {"h": "Inkor va so''roq", "t": {"head": ["Shakl", "Misol"], "rows": [["Tasdiq", "I used to live in Fergana."], ["Inkor", "I didn''t use to like coffee."], ["So''roq", "Did you use to have long hair?"]]}}, {"h": "Diqqat", "p": ["used to faqat o''tmish uchun. Hozirgi odat uchun Present Simple: I usually play football."], "w": "Inkor va so''roqda d tushib qoladi: didn''t use to, Did you use to...? (didn''t used to emas)."}]'::jsonb,'["used to + fe''l: ilgari bo''lgan, hozir yo''q.", "Inkor: didn''t use to.", "So''roq: Did you use to...?"]'::jsonb,false,true);
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-19',0,'fill','{"q": "When I was a child, I ___ play in the street.", "opts": ["used to", "use to", "was used"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "used to"}'::jsonb,null from e;
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-19',1,'fill','{"q": "I didn''t ___ like vegetables.", "opts": ["use to", "used to", "using to"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "use to"}'::jsonb,'Inkorda didn''t + use to.' from e;
