insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-20','grammar','A2',18,'First Conditional','If + Present, will + fe''l','[{"h": "Real shart", "p": ["Kelajakda bo''lishi mumkin bo''lgan shart va natija uchun: If it rains, I will stay at home. (Yomg''ir yog''sa, uyda qolaman.)"], "t": {"head": ["Shart qismi", "Natija qismi"], "rows": [["If + Present Simple", "will + fe''l"], ["If you study,", "you will pass the exam."], ["If she doesn''t hurry,", "she will miss the bus."]]}}, {"h": "Tartib almashishi", "p": ["Qismlar o''rnini almashtirsa bo''ladi: I will stay at home if it rains. If boshda kelsa, o''rtaga vergul qo''yiladi."]}, {"h": "unless", "e": [["Unless you hurry, you will be late.", "Shoshilmasang, kechikasan."]], "w": "If qismida will ishlatilmaydi: If it will rain xato. To''g''risi: If it rains."}]'::jsonb,'["If + Present Simple, will + fe''l.", "If qismida will yo''q.", "unless = if ... not."]'::jsonb,false,true);
with e as (insert into content_exercises(lesson_id,ord,type,data) values ('a2-20',0,'fill','{"q": "If it ___ tomorrow, we will stay at home.", "opts": ["rains", "will rain", "rained"]}'::jsonb) returning id) insert into content_answers(exercise_id,answer,why) select id,'{"a": "rains"}'::jsonb,'If qismida Present Simple.' from e;
