insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-21','grammar','A2',19,'too va enough','Haddan tashqari va yetarli','[{"h": "too: haddan tashqari", "p": ["too + sifat \"juda (ortiqcha)\" degani, salbiy ma''noda: This coffee is too hot. (Bu qahva juda issiq, ichib bo''lmaydi.)"]}, {"h": "enough: yetarli", "t": {"head": ["Tuzilma", "Misol"], "rows": [["sifat + enough", "He isn''t tall enough."], ["enough + ot", "We don''t have enough money."], ["too + sifat + to + fe''l", "It''s too cold to swim."], ["sifat + enough + to + fe''l", "She is old enough to drive."]]}}, {"h": "too va very", "e": [["The bag is very heavy, but I can carry it.", "Sumka juda og''ir, lekin ko''tara olaman."], ["The bag is too heavy. I can''t carry it.", "Sumka haddan tashqari og''ir, ko''tara olmayman."]], "w": "enough sifatdan keyin keladi: enough tall emas, tall enough."}]'::jsonb,'["too + sifat: ortiqcha, muammo bor.", "sifat + enough: yetarli.", "enough + ot: enough money."]'::jsonb,false,true);
