insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-22','grammar','A2',20,'who, which, that','Aniqlovchi ergash gaplar','[{"h": "Kim? Qaysi?", "p": ["who, which, that ikki gapni bog''lab, kim yoki nima haqida gapirayotganimizni aniqlaydi."], "t": {"head": ["So''z", "Kim/nima uchun", "Misol"], "rows": [["who", "odamlar", "The man who lives next door is a doctor."], ["which", "narsa, hayvon", "The book which I bought is interesting."], ["that", "odam ham, narsa ham", "The girl that sings well is my sister."]]}}, {"h": "O''zbekchaga tarjima", "e": [["The teacher who teaches us is kind.", "Bizga dars beradigan o''qituvchi mehribon."], ["I have a phone which takes good photos.", "Menda yaxshi rasm oladigan telefon bor."]]}, {"h": "Diqqat", "p": ["O''zbekchada \"-gan, -digan\" qo''shimchasi ishlatiladi, inglizchada esa who/which/that so''zi kerak."], "w": "Odam uchun which ishlatilmaydi: the man which xato. To''g''risi: the man who."}]'::jsonb,'["who: odamlar.", "which: narsalar, hayvonlar.", "that: ikkalasi uchun ham."]'::jsonb,false,true);
