insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-23','grammar','A2',21,'-ing yoki to + fe''l','enjoy doing, want to do','[{"h": "Fe''ldan keyin -ing", "p": ["Ba''zi fe''llardan keyin ikkinchi fe''l -ing shaklida keladi."], "t": {"head": ["Fe''l", "Misol"], "rows": [["enjoy", "I enjoy reading."], ["finish", "She finished cooking."], ["stop", "Stop talking!"], ["mind", "Do you mind waiting?"], ["go + sport", "Let''s go swimming."]]}}, {"h": "Fe''ldan keyin to + fe''l", "t": {"head": ["Fe''l", "Misol"], "rows": [["want", "I want to sleep."], ["need", "You need to rest."], ["decide", "We decided to stay."], ["hope", "I hope to see you."], ["learn", "She is learning to drive."]]}}, {"h": "Predlogdan keyin -ing", "e": [["I''m interested in learning English.", "Ingliz tilini o''rganishga qiziqaman."], ["She is good at drawing.", "U rasm chizishni yaxshi biladi."]], "w": "want doing yoki enjoy to read deyilmaydi. Har bir fe''lning shaklini yodlash kerak."}]'::jsonb,'["enjoy, finish, stop, mind + -ing.", "want, need, decide, hope, learn + to + fe''l.", "Predlogdan keyin doim -ing: good at swimming."]'::jsonb,false,true);
