insert into content_lessons(id,track,level,ord,title,sub,theory,summary,review,published) values ('a2-24','grammar','A2',22,'Egalik olmoshlari va sanaladigan otlar','mine, yours; a / some / any','[{"h": "mine, yours, his...", "p": ["Egalik olmoshi otsiz ishlatiladi: This book is mine. (Bu kitob meniki.)"], "t": {"head": ["Ot bilan", "Otsiz"], "rows": [["my book", "mine"], ["your book", "yours"], ["his book", "his"], ["her book", "hers"], ["our book", "ours"], ["their book", "theirs"]]}}, {"h": "Whose?", "e": [["Whose phone is this? It''s hers.", "Bu kimning telefoni? Uniki."]]}, {"h": "Sanaladigan va sanalmaydigan otlar", "t": {"head": ["Sanaladigan", "Sanalmaydigan"], "rows": [["an apple, two apples", "water, rice, money, bread"], ["How many apples?", "How much water?"], ["a few books", "a little milk"]]}, "w": "Sanalmaydigan otlarga a/an qo''yilmaydi va ko''plik -s qo''shilmaydi: a water, breads xato. To''g''risi: some water, some bread."}]'::jsonb,'["mine, yours, his, hers, ours, theirs: otsiz.", "Whose...? = Kimning...?", "Sanalmaydigan otlar: a/an va -s yo''q, much / a little."]'::jsonb,false,true);
